export interface AutomationEngineEventSequenceValidator {
  readonly cursor: number
  accept(event: AutomationEngineEvent): void
}

/** Validates events before Den persists them and advances its durable cursor. */
export function createAutomationEngineEventSequenceValidator(
  rawReceipt: AutomationEngineAdmissionReceipt,
  afterSequence = 0,
): AutomationEngineEventSequenceValidator {
  const receipt = automationEngineAdmissionReceiptSchema.parse(rawReceipt)
  if (!Number.isSafeInteger(afterSequence) || afterSequence < 0) {
    throw new Error("Automation engine event cursor must be a non-negative integer")
  }
  let cursor = afterSequence
  const eventKeys = new Set<string>()
  return {
    get cursor() {
      return cursor
    },
    accept(rawEvent) {
      const event = automationEngineEventSchema.parse(rawEvent)
      if (event.executionId !== receipt.executionId || event.runId !== receipt.runId) {
        throw new Error("Automation engine event receipt mismatch")
      }
      if (event.sequence !== cursor + 1) {
        throw new Error("Automation engine event sequence is not contiguous")
      }
      if (eventKeys.has(event.idempotencyKey)) {
        throw new Error("Automation engine event idempotency key was repeated")
      }
      eventKeys.add(event.idempotencyKey)
      cursor = event.sequence
    },
  }

const initialAuthorityFailure = await currentAgentAuthority(input)
if (initialAuthorityFailure) return initialAuthorityFailure
const runtime = await resolveCloudAgentReadyWorker(input, signal)
if (!runtime.ok) {
  return cloudAgentRuntimeUnavailableResult({
    reason: runtime.reason,
    message: runtime.message,
    cancelled: input.signal.aborted,
    timedOut: deadlineController.signal.aborted,
  })
}

const previousReceipt = parseReceipt(input.previousReceipt)
if (input.previousReceipt && !previousReceipt) {
  return { ok: false, status: "failed", code: "execution_runtime_unavailable", message: "The saved Cloud execution receipt is incomplete and cannot be recovered safely.", retryable: false, needsAttention: true }
}
if (previousReceipt && previousReceipt.workerId !== runtime.workerId) {
  return { ok: false, status: "failed", code: "execution_runtime_unavailable", message: "The Cloud worker changed while this Automation run was recovering.", retryable: false, needsAttention: true }
}

// Recovery keeps the receipt's workspace (the turn may already be running
// there); otherwise the revision pin wins over the worker's active workspace.
const workspaceId = previousReceipt?.workspaceId ?? input.workspaceId ?? runtime.workspaceId
const connect = await connectHealth({
  organizationId: input.organizationId,
  workerId: runtime.workerId,
  baseUrl: runtime.baseUrl,
  access: runtime.access,
  workspaceId,
  action: input.action,
  signal,
})
if (!connect.ok) {
  return { ok: false, status: "failed", code: connect.code, message: connect.message, retryable: false, needsAttention: true }
}

client = createHeadlessThreadClient({
  baseUrl: runtime.baseUrl,
  workspaceId,
  token: runtime.access.clientToken,
  hostToken: runtime.access.hostToken,
  requestTimeoutMs: WORKER_REQUEST_TIMEOUT_MS,
  fetch: (url, init = {}) => fetchPreviewNoRedirect(previewFetch(), url, init),
  defaultModel: {
    providerId: input.action.model.providerId,
    modelId: input.action.model.modelId,
    ...(input.action.model.variant ? { variant: input.action.model.variant } : {}),
  },
})

const messageId = previousReceipt?.messageId ?? messageIdForRun(input.automationRunId)
nativeThreadId = previousReceipt?.nativeThreadId ?? null
const recoveringNativeThread = nativeThreadId !== null
if (!nativeThreadId) {
  // Wake-up and Connect repair can take minutes. Re-check live authority at
  // the native-thread boundary so queued recovery cannot use credentials
  // materialized before the owner or model grant was revoked.
  const authorityFailure = await currentAgentAuthority(input)
  if (authorityFailure) return authorityFailure
  const thread = await client.createThread({ title: `Automation: ${input.automationName}`, signal })
  nativeThreadId = thread.id
  // Persist the native session and stable user-message id before any work
  // is submitted. Recovery can now observe-or-submit the exact same turn.
  await input.onAdmitted({ workerId: runtime.workerId, workspaceId, nativeThreadId, messageId })
}

// Thread creation and receipt persistence are also asynchronous. Make the
// final authorization decision immediately before submitting the turn.
const authorityFailure = await currentAgentAuthority(input)
if (authorityFailure) {
  // A recovered receipt may refer to a turn admitted by a previous Den
  // process. Do not terminalize the run until that thread is observably
  // stopped, or a retry could overlap side effects from the revoked turn.
  if (recoveringNativeThread && !await abortAndObserve(client, nativeThreadId)) {
    return {
      ok: false,
      status: "failed",
      code: "execution_failed",
      message: "Model authority was revoked, but OpenWork Cloud could not confirm that the native thread stopped. Inspect the native run before retrying.",
      retryable: false,
      needsAttention: true,
      events: [{ type: "warning", payload: { code: "authority_revoked_abort_not_observed", nativeThreadId } }],
    }
  }
  return authorityFailure
}
const accepted = await client.sendTurn(nativeThreadId, {
  prompt: input.action.instructions,
  messageId,
  signal,
})

if (waited.outcome !== "settled") {
  const stopped = await abortAndObserve(client, nativeThreadId)
  const cancelled = input.signal.aborted
  if (!stopped) {
    return {
      ok: false,
      status: "failed",
      code: "execution_failed",
      message: "OpenWork Cloud could not confirm that the cancelled agent thread stopped. Inspect the native run before retrying.",
      retryable: false,
      needsAttention: true,
      events: [{ type: "warning", payload: { code: "abort_not_observed", nativeThreadId } }],
    }
  }
  return {
    ok: false,
    status: cancelled ? "cancelled" : "failed",
    code: cancelled ? "cancelled" : "execution_timed_out",
    message: cancelled ? "The Automation run was cancelled." : "The Automation run exceeded its maximum runtime.",
    retryable: false,
    events: [{ type: "terminal", payload: { status: cancelled ? "cancelled" : "failed" } }],
  }

const scopes = readScopes(payload)
if (!scopes.has("mcp:read") && !scopes.has("mcp:write")) {
  const message = "The MCP bearer token is missing required MCP scopes."
  return mcpJsonResponse(403, {
    error: "insufficient_mcp_scope",
    oauthError: "insufficient_scope",
    message,
    referenceId,
    scope: DEN_MCP_REQUESTED_SCOPE,
  }, bearerChallenge({ metadataUrl: options.metadataUrl, error: "insufficient_scope", message }))
}

if (readStringClaim(payload, DEN_MCP_TOKEN_USE_CLAIM) !== "mcp") {
  const message = "The bearer token is not an MCP access token."
  return mcpJsonResponse(401, {
    error: "wrong_token_use",
    oauthError: "invalid_token",
    message,
    referenceId,
  }, bearerChallenge({ metadataUrl: options.metadataUrl, error: "invalid_token", message }))
}

if (!hasAcceptedResource(payload, source, options)) {
  const message = "The MCP bearer token was issued for a different resource."
  return mcpJsonResponse(401, {
    error: "wrong_mcp_resource",
    oauthError: "invalid_token",
    message,
    referenceId,
  }, bearerChallenge({ metadataUrl: options.metadataUrl, error: "invalid_token", message }))
}

const userId = typeof payload.sub === "string" ? payload.sub : null
const organizationId = readStringClaim(payload, DEN_MCP_ORG_ID_CLAIM)
if (!userId || !organizationId) {
  const message = "The MCP bearer token is missing its user or organization principal."
  return mcpJsonResponse(401, {
    error: "missing_mcp_principal",
    oauthError: "invalid_token",
    message,
    referenceId,
  }, bearerChallenge({ metadataUrl: options.metadataUrl, error: "invalid_token", message }))
}

const grantId = readStringClaim(payload, DEN_MCP_GRANT_ID_CLAIM)
if (grantId) {
  const grantLiveness = await getMcpGrantLiveness(grantId)
  if (grantLiveness === "check_failed") {
    return mcpJsonResponse(503, {
      error: "mcp_grant_check_unavailable",
      message: "OpenWork could not verify the token grant. Retry shortly.",
      referenceId,
    }, undefined, { "retry-after": "10" })
  }

  if (grantLiveness === "missing") {
    const message = "The MCP bearer token grant is missing or revoked."
    return mcpJsonResponse(401, {
      error: "mcp_grant_revoked",
      oauthError: "invalid_token",
      message,
      referenceId,
    }, bearerChallenge({ metadataUrl: options.metadataUrl, error: "invalid_token", message }))
  }
} else {
  const sessionId = readStringClaim(payload, "sid")
  if (!sessionId) {
    const message = "The MCP bearer token is not tied to an active session."
    return mcpJsonResponse(401, {
      error: "mcp_session_required",
      oauthError: "invalid_token",
      message,
      referenceId,
    }, bearerChallenge({ metadataUrl: options.metadataUrl, error: "invalid_token", message }))
  }

  const sessionLiveness = await getMcpSessionLiveness(sessionId)
  if (sessionLiveness === "check_failed") {
    return mcpJsonResponse(503, {
      error: "mcp_session_check_unavailable",
      message: "OpenWork could not verify the token session. Retry shortly.",
      referenceId,
    }, undefined, { "retry-after": "10" })
  }

  if (sessionLiveness === "missing") {
    const message = "The MCP bearer token session is missing, expired, or revoked."
    return mcpJsonResponse(401, {
      error: "mcp_session_revoked",
      oauthError: "invalid_token",
      message,
      referenceId,
    }, bearerChallenge({ metadataUrl: options.metadataUrl, error: "invalid_token", message }))
  }
}

if (!(await hasActiveMcpMembership({ userId, organizationId }))) {
  return mcpJsonResponse(403, {
    error: "mcp_membership_revoked",
    message: "The MCP bearer token's organization membership is no longer active.",
    referenceId,
  })
}

return { userId, organizationId, scopes, payload }

export async function getMcpGrantLiveness(grantId: string): Promise<McpGrantLiveness> {
  let normalizedGrantId: NormalizedMcpGrantId
  try {
    normalizedGrantId = normalizeMcpGrantId(grantId)
  } catch {
    return "missing"
  }

  try {
    const rows = await activeMcpGrantSelect({ normalizedGrantId })
    return rows.length > 0 ? "live" : "missing"
  } catch (error) {
    console.error("mcp_grant_liveness_check_failed", livenessLogDetails(normalizedGrantId, error))
    return "check_failed"
  }

